// Maps level paths from the replay header ("/Game/Maps/Jam/Jam") to display names ("Lotus"),
// the minimap transform (world cm -> minimap UV) and named callouts in world coordinates (Unreal cm, Z-up).
// Standalone file: works in Unity and in ValorantReplay.Core. Unknown (newer) maps fall back to the level name.
using System;
using System.Collections.Generic;

namespace ValorantReplay.Playback
{
    public sealed class Callout
    {
        public readonly string SuperRegion, Region;   // "A", "Site"
        public readonly float X, Y, Z;
        public Callout(string superRegion, string region, float x, float y, float z)
        {
            SuperRegion = superRegion; Region = region; X = x; Y = y; Z = z;
        }
        public string Name => SuperRegion + " " + Region;
        public override string ToString() => Name;
    }

    public sealed class MapInfo
    {
        public readonly string MapUrl, DisplayName, Uuid, Sites, MinimapUrl;
        public readonly float XMultiplier, YMultiplier, XScalarToAdd, YScalarToAdd;
        public readonly Callout[] Callouts;
        public MapInfo(string mapUrl, string displayName, string uuid, string sites,
                       float xMultiplier, float yMultiplier, float xScalarToAdd, float yScalarToAdd, string minimapUrl, Callout[] callouts)
        {
            MapUrl = mapUrl; DisplayName = displayName; Uuid = uuid; Sites = sites;
            XMultiplier = xMultiplier; YMultiplier = yMultiplier; XScalarToAdd = xScalarToAdd; YScalarToAdd = yScalarToAdd;
            MinimapUrl = minimapUrl; Callouts = callouts;
        }

        /// <summary>True for maps with a minimap transform (standard/competitive maps, not the Range or TDM maps).</summary>
        public bool HasMinimap => XMultiplier != 0f;

        /// <summary>World position (Unreal cm) -> minimap UV in [0,1], u to the right, v downward (image space of MinimapUrl).
        /// Note the axis swap: u comes from world Y, v from world X.</summary>
        public void ToMinimap(float x, float y, out float u, out float v)
        {
            u = y * XMultiplier + XScalarToAdd;
            v = x * YMultiplier + YScalarToAdd;
        }

        /// <summary>Nearest named callout by 2D distance (e.g. "A Site"), or null if the map has none.</summary>
        public Callout NearestCallout(float x, float y)
        {
            Callout best = null;
            float bd = float.MaxValue;
            foreach (var c in Callouts)
            {
                float dx = c.X - x, dy = c.Y - y, d = dx * dx + dy * dy;
                if (d < bd) { bd = d; best = c; }
            }
            return best;
        }

        public override string ToString() => DisplayName;
    }

