        private static readonly Dictionary<string, MapInfo> ByUrl = new Dictionary<string, MapInfo>(StringComparer.OrdinalIgnoreCase);
        private static readonly Dictionary<string, MapInfo> ByLevel = new Dictionary<string, MapInfo>(StringComparer.OrdinalIgnoreCase);

        static MapCatalog()
        {
            foreach (var m in All) { ByUrl[m.MapUrl] = m; ByLevel[LevelName(m.MapUrl)] = m; }
        }

        /// <summary>"/Game/Maps/Jam/Jam" -> "Jam".</summary>
        public static string LevelName(string levelPath)
        {
            if (string.IsNullOrEmpty(levelPath)) return "";
            int slash = levelPath.LastIndexOf('/');
            return slash >= 0 ? levelPath.Substring(slash + 1) : levelPath;
        }

        /// <summary>Lookup by full level path, then by level name. Null if unknown.</summary>
        public static MapInfo Find(string levelPath)
        {
            if (string.IsNullOrEmpty(levelPath)) return null;
            if (ByUrl.TryGetValue(levelPath, out var m)) return m;
            return ByLevel.TryGetValue(LevelName(levelPath), out m) ? m : null;
        }

        /// <summary>Display name ("Lotus"), or the internal level name if the map is newer than this catalog.</summary>
        public static string DisplayName(string levelPath)
        {
            var m = Find(levelPath);
            return m != null ? m.DisplayName : LevelName(levelPath);
        }
    }
